impl<C: FlagClient> Rollout<C> {
    pub async fn is_enabled(&self, key: &str, user_id: &str, percent: u32) -> bool {
        let cfg = match self.flags.fetch(key).await { //!issue:2
            Ok(cfg) => cfg,
            Err(_) => return true, //!issue:4
        };
        if cfg.allowlist.iter().any(|u| u == user_id) {
            return true;
        }
        let bucket = rand::random::<u32>() % 100; //!issue:1
        bucket < percent //!issue:3
    }
}

