// One-off job: convert invoices.amount from dollars to integer cents.
export async function backfillInvoiceCents(pool: Pool, log: Logger): Promise<void> {
  const client = await pool.connect();
  try {
    await client.query("BEGIN"); //!issue:2
    await client.query("LOCK TABLE invoices IN EXCLUSIVE MODE"); //!issue:1
    log.info("starting invoice cents backfill");
    const res = await client.query(
      "UPDATE invoices SET amount = amount * 100, amount_unit = 'cents'" //!issue:1,3
    );
    await client.query("COMMIT");
    log.info(`backfill complete: ${res.rowCount} rows`); //!issue:4
  } catch (err) {
    await client.query("ROLLBACK");
    throw err;
  } finally {
    client.release();
  }
}

