func BackfillInvoiceCents(ctx context.Context, db *sql.DB, log *slog.Logger) error {
	tx, err := db.BeginTx(ctx, nil) //!issue:2
	if err != nil {
		return err
	}
	defer tx.Rollback()

	if _, err := tx.ExecContext(ctx, "LOCK TABLE invoices IN EXCLUSIVE MODE"); err != nil { //!issue:1
		return err
	}
	log.Info("starting invoice cents backfill")
	res, err := tx.ExecContext(ctx,
		"UPDATE invoices SET amount = amount * 100, amount_unit = 'cents'") //!issue:1,3
	if err != nil {
		return err
	}
	if err := tx.Commit(); err != nil {
		return err
	}
	n, _ := res.RowsAffected()
	log.Info("backfill complete", "rows", n) //!issue:4
	return nil
}

